package io.knowledgebrain.collaboration;
import io.knowledgebrain.contracts.collaboration.submissionfiles.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class SubmissionFilesKafkaIntegrationTest {
 @Test void exactBundleBytesArePublishedAndReplayedWithoutAcknowledgement()throws Exception{
  var test=new SubmissionFilesStoreIntegrationTest();test.setup();var f=test.f;test.submit(0,f.f.key(),List.of(test.file()));test.submit(1,f.f.key(),List.of(test.file(),test.file()));var expected=new HashMap<String,byte[]>();for(var bytes:f.f.jdbc.queryForList("SELECT o.payload FROM outbox_event o JOIN submission_file_bundle b ON o.aggregateid=b.bundle_id WHERE b.assignment_id=?",byte[].class,f.assignment)){var e=SubmissionFilesEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(2,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));

  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("collaboration.submission-files.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<2&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=SubmissionFilesEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());var p=SubmissionFilesSnapshotV1.parseFrom(e.getPayload());assertEquals(p.getBundleId(),record.key());assertEquals(f.author.toString(),e.getActorId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.f.trace,e.getTraceId());assertEquals("AUTHOR_AND_OWNER",p.getAudience());assertEquals("SubmissionFilesAttached",e.getEventType());for(var entry:Map.of("trace_id",f.f.trace,"schema_group","collaboration","schema_artifact","submission-files-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS collaboration.submission-files.v1 byte-exact private version bundles, trace/schema headers and unacknowledged replay");
 }
}
